discrete AudioCapture
port:
    event input real StartRecording;
    event output real AudioData;
state:
    initial state StandbyState
        when entry() then
            statehold(5);
        end;

        when receive(StartRecording) then
            transition(RecordingState);
        end;
    end;

    state RecordingState
        when entry() then
            statehold(60);
        end;

        when timeover() then
            transition(StandbyState);
            out
                send(AudioData, 1);
        end;
    end;
end;
end;

discrete SignalProcessing
port:
    event input real ProcessAudio;
    event output real ProcessedData;
state:
    initial state WaitForInput
        when entry() then
            statehold(5);
        end;

        when receive(ProcessAudio) then
            transition(ProcessingState);
        end;
    end;

    state ProcessingState
        when entry() then
            statehold(10);
        end;

        when timeover() then
            transition(WaitForInput);
            out
                send(ProcessedData, 1);
        end;
    end;
end;
end;

discrete SpeechRecognition
port:
    event input real NewAudioSample;
    event output real RecognitionResult;
state:
    initial state ReadyForRecognition
        when entry() then
            statehold(5);
        end;

        when receive(NewAudioSample) then
            transition(RecognizingState);
        end;
    end;

    state RecognizingState
        when entry() then
            statehold(15);
        end;

        when timeover() then
            transition(ReadyForRecognition);
            out
                send(RecognitionResult, 1);
        end;
    end;
end;
end;

discrete ControlFeedback
port:
    event input real TranscriptionResult;
    event output real StartRecording;
state:
    initial state Initialization
        when entry() then
            statehold(5);
        end;

        when timeover() then
            transition(ListeningMode);
        end;
    end;

    state ListeningMode
        when entry() then
            statehold(60);
        end;

        when receive(TranscriptionResult) then
            transition(ResponseMode);
        end;
    end;

    state ResponseMode
        when entry() then
            statehold(10);
        end;

        when timeover() then
            transition(ListeningMode);
            out
                send(StartRecording, 1);
        end;
    end;
end;
end;

couple VoiceRecognitionSystem
import architectureModels.AudioCapture as AC;
import architectureModels.SignalProcessing as SP;
import architectureModels.SpeechRecognition as SR;
import architectureModels.ControlFeedback as CF;
part:
    AC audioCaptureInstance;
    SP signalProcessingInstance;
    SR speechRecognitionInstance;
    CF controlFeedbackInstance;
connection:
    connect(audioCaptureInstance.AudioOutput, signalProcessingInstance.AudioInput);
    connect(signalProcessingInstance.ProcessedOutput, speechRecognitionInstance.AudioInput);
    connect(speechRecognitionInstance.ResultOutput, controlFeedbackInstance.TranscriptionInput);
    connect(controlFeedbackInstance.CommandOutput, audioCaptureInstance.CommandInput);
end;
